<template><section aria-label="受审合成本地练习"><p>练习使用已审核的合成材料；提交后显示答案和解析，不用于诊疗或能力认证。</p><p v-if="!allowed" role="alert">当前身份或会话不可读取练习。</p><template v-else><p v-if="error" role="alert">{{error}}</p><el-button :disabled="busy" @click="directory('published')">选择课程</el-button><el-button :disabled="busy" @click="directory('own-submissions')">我的练习记录</el-button><p v-if="list">第{{list.page}}页</p><table v-if="list"><tbody><tr v-for="row in list.items" :key="row.review_id+' '+(row.submission_id||'')"><td>{{row.title||row.submission_id}} {{row.version_label}}</td><td><el-button :disabled="busy" @click="kind==='published'?choose(row):openPractice(row)">{{kind==='published'?'开始练习':'查看答案与解析'}}</el-button></td></tr></tbody></table><template v-if="list"><el-button :disabled="list.page<=1||busy" @click="directory(kind,list.page-1)">上一页</el-button><el-button :disabled="!list.has_more||busy" @click="directory(kind,list.next_page)">下一页</el-button></template>
<article v-if="lesson" aria-label="无答案完整公开题面"><h3>{{lesson.title}}</h3><p>课程版本：{{lesson.version_label}}</p><details><summary>课程核验标识</summary><p>完整公开SHA：{{publicHash}}</p></details><pre>{{lesson.scenario_text}}</pre><ul><li v-for="objective in lesson.learning_objectives" :key="objective">{{objective}}</li></ul><section v-for="(q,i) in lesson.questions" :key="q.question_id"><h4>{{i+1}}. {{q.stem}}</h4><el-radio-group v-if="q.selection==='single'" v-model="choices[q.question_id][0]" :aria-label="'题目'+(i+1)" :disabled="busy||!!feedback"><el-radio v-for="option in q.options" :key="option.option_id" :value="option.option_id">{{option.text}}</el-radio></el-radio-group><el-checkbox-group v-else v-model="choices[q.question_id]" :aria-label="'题目'+(i+1)" :disabled="busy||!!feedback"><el-checkbox v-for="option in q.options" :key="option.option_id" :value="option.option_id">{{option.text}}</el-checkbox></el-checkbox-group></section><template v-if="!feedback"><el-checkbox v-model="confirmed" :disabled="busy">确认提交本次作答（未选择的题目记为未作答）</el-checkbox><el-button :disabled="!confirmed||busy" @click="submit">提交练习并查看解析</el-button></template><el-button @click="clear">清除本课程和答案</el-button></article>
<article v-if="feedback" aria-label="实际提交后的固定练习反馈"><h3>练习结果与解析</h3><p>共{{feedback.question_count}}题，答对{{feedback.matching_count}}题，答错{{feedback.differing_count}}题，未作答{{feedback.unanswered_count}}题。按课程审核答案核对，未调用模型。</p><section v-for="(row,i) in feedback.questions" :key="row.question_id"><h4>题目{{i+1}}：{{({matches_reviewed_key:'答对',differs_from_reviewed_key:'答错',explicitly_unanswered:'未作答'})[row.outcome]||row.outcome}}</h4><p>参考答案：{{row.correct_option_ids.map(k=>lesson.questions[i].options.find(o=>o.option_id===k)?.text).join('；')}}</p><pre>{{row.reviewed_rationale}}</pre><el-button v-for="id in row.reference_ids" :key="id" @click="showReference(id)">查看参考资料：{{references.find(r=>r.document_id===id)?.title}}</el-button></section></article></template><el-dialog :model-value="referenceOpen" title="本次受审练习的完整原参考" :close-on-click-modal="false" :before-close="done=>{closeReference();done();}"><template v-if="reference"><h3>{{reference.title}} {{reference.version}}</h3><details><summary>参考资料核验标识</summary><p>完整原UTF8 SHA：{{reference.content_utf8_sha256}}</p></details><pre>{{reference.content}}</pre></template></el-dialog></section></template>
<script setup>
import{ref,toRaw}from'vue';import{useClinicalTrainingSession}from'./useClinicalTrainingSession';import{trainingCanonical,trainingSame,trainingId}from'@/api/ai/clinicalTrainingCore';import{getTrainingDirectory,verifyTrainingDirectory,getTrainingPublishedLesson,verifyTrainingPublicLesson,verifyTrainingPublicPart,submitTrainingPractice,getTrainingPractice,getTrainingPracticePart,verifyTrainingPracticeMetadata,verifyTrainingPracticeParts,verifyTrainingSubmission}from'@/api/ai/clinicalTrainingSources';
const props=defineProps({active:{type:Boolean,default:true},configRevision:{type:[String,Number],default:null}}),emit=defineEmits(['select','invalidate']);const list=ref(null),kind=ref('published'),lesson=ref(null),publicHash=ref(null),reviewId=ref(null),choices=ref({}),confirmed=ref(false),receipt=ref(null),feedback=ref(null),references=ref([]),busy=ref(false),error=ref(''),reference=ref(null),referenceOpen=ref(false);let accepted=new WeakMap(),viewEpoch=0;
function clearBody(){viewEpoch++;lesson.value=null;publicHash.value=null;reviewId.value=null;choices.value={};confirmed.value=false;receipt.value=null;feedback.value=null;references.value=[];reference.value=null;referenceOpen.value=false;emit('select',null);emit('invalidate');}
function reset(){clearBody();list.value=null;accepted=new WeakMap();busy.value=false;error.value='';}
const session=useClinicalTrainingSession(props,reset),allowed=session.allowed;
function clear(){session.advance();clearBody();error.value='';}
function rowAccepted(row){return accepted.get(toRaw(row))===trainingCanonical(row);}
async function directory(next,page=1){session.advance();reset();if(!allowed.value)return;const t=session.ticket();busy.value=true;kind.value=next;try{const v=(await getTrainingDirectory(next,{page})).data;if(!session.current(t))return;if(!verifyTrainingDirectory(v,next,{page}))throw new Error('完整技术目录无法核对');accepted=new WeakMap(v.items.map(x=>[x,trainingCanonical(x)]));list.value=v;}catch(e){if(session.current(t)){reset();error.value=e.message||'当前课程目录不可读';}}finally{if(session.current(t))busy.value=false;}}
async function choose(row){if(!allowed.value||busy.value||kind.value!=='published'||!rowAccepted(row))return;session.advance();clearBody();error.value='';const t=session.ticket();busy.value=true;try{const p=await getTrainingPublishedLesson(row.review_id);if(!session.current(t))return;if(!await verifyTrainingPublicLesson(p,row,{current:()=>session.current(t)}))throw new Error('完整公开题面、原SHA或审核版本不同');lesson.value=p.value;publicHash.value=p.wire.public_source_sha256;reviewId.value=row.review_id;choices.value=Object.fromEntries(p.value.questions.map(q=>[q.question_id,[]]));}catch(e){if(session.current(t)){clearBody();error.value=e.message||'当前完整题面不可读';}}finally{if(session.current(t))busy.value=false;}}
async function loadPractice(meta,t,submitted=null){if(!verifyTrainingPracticeMetadata(meta))throw new Error('实际提交回执损坏');const p=await getTrainingPublishedLesson(meta.review_id);if(!session.current(t))return null;if(!await verifyTrainingPublicPart(p,{reviewId:meta.review_id,lessonId:meta.lesson_id,current:()=>session.current(t)}))throw new Error('当前课程已失效或题面不同');const parts=Object.fromEntries(await Promise.all(['submission','feedback','references'].map(async k=>[k,await getTrainingPracticePart(meta.submission_id,k)])));if(!session.current(t))return null;if(!await verifyTrainingPracticeParts(meta,parts,{publicLesson:p.value,submitted,current:()=>session.current(t)}))throw new Error('完整作答、固定计数、审核解析或原参考无法核对');return{meta,public:p.value,hash:p.wire.public_source_sha256,parts};}
function accept(v){clearBody();receipt.value=v.meta;lesson.value=v.public;publicHash.value=v.hash;reviewId.value=v.meta.review_id;choices.value=Object.fromEntries(v.parts.submission.value.answers.map(a=>[a.question_id,[...a.selected_option_ids]]));feedback.value=v.parts.feedback.value;references.value=v.parts.references.value.references;emit('select',{clinical_training_submission_id:v.meta.submission_id});}
async function openPractice(row){if(!allowed.value||busy.value||kind.value!=='own-submissions'||!rowAccepted(row))return;session.advance();clearBody();error.value='';const t=session.ticket();busy.value=true;try{const meta=(await getTrainingPractice(row.submission_id)).data;if(!session.current(t))return;if(meta.submission_id!==row.submission_id||meta.review_id!==row.review_id||meta.lesson_id!==row.lesson_id)throw new Error('实际目录与提交绑定不同');const v=await loadPractice(meta,t);if(session.current(t)&&v)accept(v);}catch(e){if(session.current(t)){clearBody();error.value=e.message||'当前提交不可读';}}finally{if(session.current(t))busy.value=false;}}
async function submit(){if(!allowed.value||!lesson.value||!confirmed.value||busy.value)return;const submitted={lesson_id:lesson.value.lesson_id,public_source_sha256:publicHash.value,answers:lesson.value.questions.map(q=>({question_id:q.question_id,selected_option_ids:[...choices.value[q.question_id]]}))};if(!verifyTrainingSubmission(submitted,lesson.value))return;const body={review_id:reviewId.value,submission:submitted},t=session.ticket();busy.value=true;try{const ack=(await submitTrainingPractice(body)).data;if(!session.current(t))return;if(!verifyTrainingPracticeMetadata(ack,{reviewId:body.review_id,lessonId:submitted.lesson_id}))throw new Error('提交后实际回执无法核对');const meta=(await getTrainingPractice(ack.submission_id)).data;if(!session.current(t))return;if(!trainingSame(meta,ack))throw new Error('独立GET与已提交实际回执不同');const v=await loadPractice(meta,t,submitted);if(session.current(t)&&v)accept(v);}catch(e){if(session.current(t)){clearBody();error.value=e.message||'当前提交或来源不可用';}}finally{if(session.current(t))busy.value=false;}}
function closeReference(){viewEpoch++;referenceOpen.value=false;reference.value=null;}
async function showReference(id){closeReference();if(!allowed.value||!receipt.value||busy.value||!trainingId(id))return;const t=session.ticket(),epoch=viewEpoch,meta=receipt.value;referenceOpen.value=true;try{const fresh=(await getTrainingPractice(meta.submission_id)).data;if(!session.current(t)||epoch!==viewEpoch||!referenceOpen.value)return;if(!trainingSame(meta,fresh))throw new Error('当前提交版本不同');const v=await loadPractice(fresh,t);if(!session.current(t)||epoch!==viewEpoch||!referenceOpen.value||!v)return;const found=v.parts.references.value.references.find(r=>r.document_id===id);if(!found)throw new Error('实际所选参考不存在');reference.value=found;}catch(e){if(session.current(t)&&epoch===viewEpoch&&referenceOpen.value){clearBody();error.value=e.message||'当前原参考不可读';}}}
</script><style scoped>section{display:grid;gap:12px}article{border:1px solid #ddd;padding:16px}pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:50vh;overflow:auto}.el-radio-group,.el-checkbox-group{display:grid;gap:8px}table{width:100%}</style>
